-- Switzerland: milestones + English translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ch-fedcouncil-einvoicing-decision', id, '2014-10-08', 1, 'https://www.vtg.admin.ch/de/e-rechnung', 0, '[]', NULL, 'none', 'unreviewed' FROM countries WHERE code = 'CH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ch-fedcouncil-einvoicing-decision', 'en', 'The Federal Council decides to oblige federal suppliers to invoice electronically', 'The Federal Council resolved to require suppliers to the federal administration to submit electronic invoices where the contract value exceeds CHF 5,000, with effect from 1 January 2016. The threshold was set to spare smaller suppliers.', '["Background to the 2016 obligation rather than a duty in itself"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ch-b2g-supplier-duty', id, '2016-01-01', 0, 'https://www.efv.admin.ch/de/e-rechnungen-zustellen', 1, '[{"label": "Sending e-invoices to the Confederation", "url": "https://www.efv.admin.ch/de/e-rechnungen-zustellen"}]', NULL, 'b2g_only', 'live' FROM countries WHERE code = 'CH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ch-b2g-supplier-duty', 'en', 'Suppliers to the central federal administration must invoice electronically above CHF 5,000', 'The obligation takes effect. It binds the supplier to issue, not the authority to receive, and the binding text is clause 9.4 of the Confederation''s procurement standard terms rather than an ordinance in the Systematic Compilation. The threshold is CHF 5,000 excluding VAT, a qualifier only the standard terms carry. Cantons, communes and the ETH domain are outside it.', '["Check whether your counterparty is a central federal unit -- the published list decides it", "Below CHF 5,000 excluding VAT, paper is still permitted"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ch-pdf-counts-as-electronic', id, '2018-06-27', 0, 'https://www.admin.ch/de/nsb?id=71361', 0, '[]', NULL, 'none', 'unreviewed' FROM countries WHERE code = 'CH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ch-pdf-counts-as-electronic', 'en', 'The Confederation confirms a PDF sent by e-mail satisfies the obligation', 'Reporting that the e-invoice share had risen fourfold to around 60 per cent, the Federal Finance Administration confirmed that the federal administration also accepts PDF invoices sent by e-mail. The duty is to invoice without paper, not to invoice in a structured format -- the single most consequential fact about this country for anyone scoping an integration.', '["Do not provision a structured pipeline on the strength of the 2016 date alone"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ch-vat-filing-online-mandatory', id, '2025-01-01', 0, 'https://www.estv.admin.ch/de/mwst-online-abrechnen', 1, '[{"label": "ESTV -- filing VAT online", "url": "https://www.estv.admin.ch/de/mwst-online-abrechnen"}]', NULL, 'none', 'live' FROM countries WHERE code = 'CH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ch-vat-filing-online-mandatory', 'en', 'Electronic VAT filing becomes compulsory for every registered business', 'Article 65a of the VAT Act, introduced by the partial revision in force from 1 January 2024 with a year''s transition, makes online filing through the Federal Tax Administration''s portal the only route. This is a filing channel and not a reporting regime: periodic aggregate returns are submitted, and no invoice or transaction data reaches the administration.', '["Register for the ESTV portal if you file Swiss VAT", "Do not read this as e-reporting -- no transaction data is transmitted"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ch-zurich-digital-standard-2027', id, '2026-06-25', 0, 'https://www.zh.ch/de/news-uebersicht/medienmitteilungen/2026/06/kanton-verarbeitet-rechnungen-durchgaengig-elektronisch.html', 0, '[]', NULL, 'none', 'unreviewed' FROM countries WHERE code = 'CH';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ch-zurich-digital-standard-2027', 'en', 'The Canton of Zurich makes digital invoice delivery its standard from 2027', 'The cantonal government declared digital delivery the standard from 2027, with paper becoming the exception. Suppliers are invited rather than obliged, no threshold is set, and no format is prescribed. The federal obligation does not reach cantons, so this is the current frontier of cantonal practice rather than a new duty.', '["Watch cantonal practice separately from the federal rule -- they are different regimes"]');

